o":"50H93284","ngay_vao":"2026-10-06","nguon_tt":"bao_hiem","hang_bh":"Tasco","gdv":"Hảo","gdv_chu":null,"than_vo":"2027-06-02","tnds":null,"tinh_trang":"Hạng mục: BẢO HIỂM – Nội dung sửa chữa: Thay đèn hậu phải, Đồng sơn cửa trước phải, đồng sơn cửa sau phải, sơn hông xe phải, cản sau phải, đồng sơn tai xe trái, sơn ốp gương chiếu hậu trái phải – Ghi chú: Tasco làm vụ 2 tại gara – Khách thanh toán 3.000.000 đ","ph1":"ngày 05/10/2026 Vụ 1 đang sửa, vụ 2 vừa giám định xong và yêu cầu sửa tại gara Hoàng Sơn","ph2":null},{"bien_so":"50H34281","ngay_vao":"2026-10-06","nguon_tt":"bao_hiem","hang_bh":"Tasco","gdv":"Hảo","gdv_chu":null,"than_vo":null,"tnds":null,"tinh_trang":"Hạng mục: BẢO HIỂM – Ghi chú: Xe 16 chỗ","ph1":null,"ph2":null},{"bien_so":"50H81002","ngay_vao":"2026-10-07","nguon_tt":"khach","hang_bh":null,"gdv":null,"gdv_chu":null,"than_vo":null,"tnds":null,"tinh_trang":"Hạng mục: BẢO DƯỠNG – Khách thanh toán 542.000 đ","ph1":null,"ph2":null},{"bien_so":"50E74148","ngay_vao":"2026-10-07","nguon_tt":"khach","hang_bh":null,"gdv":null,"gdv_chu":null,"than_vo":null,"tnds":null,"tinh_trang":"Hạng mục: BẢO DƯỠNG – Khách thanh toán 478.170 đ","ph1":null,"ph2":null},{"bien_so":"70H10280","ngay_vao":"2026-10-07","nguon_tt":"bao_hiem","hang_bh":"DBV","gdv":"Hiếu","gdv_chu":null,"than_vo":"2027-07-21","tnds":null,"tinh_trang":"Hạng mục: BẢO HIỂM – Nội dung sửa chữa: Đồng sơn cốp sau, hông xe phải sơn cửa trước, cửa sau – BH thanh toán 5.558.599 đ; Khách thanh toán 2.117.622 đ","ph1":"ngày 08/10/2026 khách kêu ok, cám ơn xưởng nhiều, chưa thu tiền","ph2":null},{"bien_so":"50E60244","ngay_vao":"2026-10-07","nguon_tt":"bao_hiem","hang_bh":"DBV","gdv":"Hiếu","gdv_chu":null,"than_vo":"2027-01-20","tnds":null,"tinh_trang":"Hạng mục: BẢO HIỂM – Nội dung sửa chữa: Đồng sơn cốp sau – Ghi chú: 1 vụ cốp sau | 2 vụ 2 bên thân xe","ph1":null,"ph2":null},{"bien_so":"49C39522","ngay_vao":"2026-10-07","nguon_tt":"bao_hiem","hang_bh":"Tasco","gdv":"Sang","gdv_chu":null,"than_vo":"2027-04-10","tnds":"2027-05-05","tinh_trang":"Hạng mục: BẢO HIỂM – Nội dung sửa chữa: Sơn cản sau phải, sơn hông xe phải, sơn cửa sau trái – BH thanh toán 2.392.500 đ; Khách thanh toán 1.000.000 đ","ph1":null,"ph2":null},{"bien_so":"50E24594","ngay_vao":"2026-10-08","nguon_tt":"khach","hang_bh":null,"gdv":null,"gdv_chu":null,"than_vo":null,"tnds":null,"tinh_trang":"Hạng mục: BẢO DƯỠNG – Nội dung sửa chữa: Đã giảm 15% – Ghi chú: GI – Khách thanh toán 1.317.330 đ","ph1":null,"ph2":null},{"bien_so":"29E49734","ngay_vao":"2026-10-08","nguon_tt":"bao_hiem","hang_bh":"Tasco","gdv":"Hảo","gdv_chu":null,"than_vo":null,"tnds":null,"tinh_trang":"Hạng mục: BẢO HIỂM – Ghi chú: TNDS Tasco – Khách thanh toán 20.487.225 đ","ph1":null,"ph2":null},{"bien_so":"79H12893","ngay_vao":"2026-08-21","nguon_tt":"bao_hiem","hang_bh":"Tasco","gdv":"Sang","gdv_chu":null,"than_vo":null,"tnds":null,"tinh_trang":null,"ph1":null,"ph2":null},{"bien_so":"51G24884","ngay_vao":"2026-09-01","nguon_tt":"bao_hiem","hang_bh":"DBV","gdv":"Hiếu","gdv_chu":null,"than_vo":null,"tnds":null,"tinh_trang":"Ghi chú: TNDS/BH","ph1":null,"ph2":null}]}$du_lieu$::jsonb;
  x jsonb; l jsonb;
  v_hang bigint; v_dong bigint; v_kh bigint; v_xe bigint; v_bh bigint; v_gdv bigint; v_ma text; v_n int; v_id bigint;
  v_ngay date; v_tt text;
  so_xe_moi int := 0; so_kh_moi int := 0; so_hs int := 0; so_bo_qua int := 0;
begin
  -- 1. Hãng xe, dòng xe còn thiếu trong danh mục
  for x in select * from jsonb_array_elements(j->'xe') loop
    if x->>'hang_xe' is not null then
      insert into public.hang_xe (ten) values (x->>'hang_xe') on conflict (ten) do nothing;
      insert into public.dong_xe (hang_xe_id, ten)
        select id, x->>'dong_xe' from public.hang_xe where ten = x->>'hang_xe'
        on conflict (hang_xe_id, ten) do nothing;
    end if;
  end loop;

  -- 2. Khách và xe
  for x in select * from jsonb_array_elements(j->'xe') loop
    select d.id into v_dong from public.dong_xe d join public.hang_xe h on h.id = d.hang_xe_id
      where h.ten = x->>'hang_xe' and d.ten = x->>'dong_xe';
    v_kh := null;
    if x->>'sdt' is not null then
      select id into v_kh from public.khach_hang where dien_thoai = x->>'sdt';
    end if;
    select id into v_xe from public.xe where bien_so = x->>'bien_so';
    if v_kh is null and v_xe is not null then
      select khach_hang_id into v_kh from public.xe where id = v_xe;
    end if;
    if v_kh is null then
      insert into public.khach_hang (ten, dien_thoai)
        values (coalesce(x->>'ten', 'Chưa có tên'), x->>'sdt') returning id into v_kh;
      so_kh_moi := so_kh_moi + 1;
    else
      update public.khach_hang set ten = x->>'ten' where id = v_kh and ten = 'Chưa có tên' and x->>'ten' is not null;
    end if;
    if v_xe is null then
      insert into public.xe (bien_so, dong_xe_id, mau, khach_hang_id, han_bao_hiem, han_bh_than_vo)
        values (x->>'bien_so', v_dong, x->>'mau', v_kh, (x->>'tnds')::date, (x->>'than_vo')::date);
      so_xe_moi := so_xe_moi + 1;
    else
      -- xe đã có trong phần mềm: chỉ điền chỗ còn trống
      update public.xe set
        dong_xe_id = coalesce(dong_xe_id, v_dong), mau = coalesce(mau, x->>'mau'),
        khach_hang_id = coalesce(khach_hang_id, v_kh),
        han_bao_hiem = coalesce(han_bao_hiem, (x->>'tnds')::date),
        han_bh_than_vo = coalesce(han_bh_than_vo, (x->>'than_vo')::date)
      where id = v_xe;
    end if;
  end loop;

  -- 3. Mỗi lần vào gara thành một hồ sơ "Chuyển từ Excel"
  for l in select * from jsonb_array_elements(j->'luot') loop
    select id, khach_hang_id into v_xe, v_kh from public.xe where bien_so = l->>'bien_so';
    v_ngay := (l->>'ngay_vao')::date;
    if exists (select 1 from public.ho_so where xe_id = v_xe and tu_excel
               and (ngay_vao at time zone 'Asia/Ho_Chi_Minh')::date = v_ngay) then
      so_bo_qua := so_bo_qua + 1; continue;
    end if;
    select id into v_bh from public.hang_bao_hiem where ten = l->>'hang_bh';
    v_gdv := null;
    if l->>'gdv' is not null then
      select g.id into v_gdv from public.giam_dinh_vien g
        where g.ten = l->>'gdv' and not g.la_cho_them
        order by (g.hang_id is not distinct from v_bh) desc, g.hang_id nulls last limit 1;
    end if;
    v_ma := 'TK-' || to_char(v_ngay, 'YYMM') || '-' || (l->>'bien_so'); v_n := 1;
    while exists (select 1 from public.ho_so where ma = v_ma) loop
      v_n := v_n + 1; v_ma := 'TK-' || to_char(v_ngay, 'YYMM') || '-' || (l->>'bien_so') || '-' || v_n;
    end loop;
    v_tt := to_char(v_ngay, 'DD/MM/YYYY') || ': ' || coalesce(l->>'tinh_trang', '(Excel không ghi tình trạng)');
    insert into public.ho_so (ma, chi_nhanh_id, loai, xe_id, khach_hang_id, ngay_vao, nguon_tt, hang_bh_id,
        gdv_id, gdv_ten_tam, han_bao_hiem, han_bh_than_vo, tinh_trang_xe, tu_van, trang_thai,
        cam_nhan_khach, cham_soc_ket_qua, tu_excel)
      values (v_ma, 'TK', 'sua_chua', v_xe, v_kh, (v_ngay + time '08:00') at time zone 'Asia/Ho_Chi_Minh',
        l->>'nguon_tt', case when l->>'nguon_tt' <> 'khach' then v_bh end,
        v_gdv, case when v_gdv is null then l->>'gdv_chu' end,
        (l->>'tnds')::date, (l->>'than_vo')::date, v_tt,
        to_char(v_ngay, 'DD/MM/YYYY') || ': (Chuyển từ Excel)', 'dong',
        l->>'ph1', l->>'ph2', true)
      returning id into v_id;
    insert into public.ho_so_nhat_ky (ho_so_id, tu_trang_thai, sang_trang_thai, ghi_chu)
      values (v_id, null, 'dong', 'Chuyển từ Excel (Data Khách Hàng Tô Ký.xlsx)');
    so_hs := so_hs + 1;
  end loop;

  raise notice 'Đã nhập: % xe mới, % khách mới, % hồ sơ lịch sử (% lần đã có, bỏ qua).', so_xe_moi, so_kh_moi, so_hs, so_bo_qua;
end $nhap$;

-- Kết quả
select
  (select count(*) from public.ho_so where tu_excel) as ho_so_tu_excel,
  (select count(distinct xe_id) from public.ho_so where tu_excel) as so_xe,
  (select count(*) from public.khach_hang) as tong_khach,
  (select count(*) from public.xe) as tong_xe;
